insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('40a204a5-9efa-584c-a3af-fc33c9e00d7b', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', 1, $q$The Art Fair Booth$q$, $q$كشك المعرض الفني$q$, 'demo/detective/missing-180/scene-1.webp', $q$The fair has closed, but the ticket roll, craft-kit display, and donation jar are still at the booth. Read the individual totals before accepting the event summary.$q$, $q$انتهى المعرض، لكن دفتر التذاكر وركن الحقائب الفنية ومرطبان التبرعات ما زالت على الكشك. افحص المجاميع المنفصلة قبل اعتماد ملخص الفعالية.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('6693a1ef-14d2-50b8-94fc-f31ac66849cb', '40a204a5-9efa-584c-a3af-fc33c9e00d7b', $q$ticket_sales$q$, $q$Twenty ticket stubs$q$, $q$Twenty ticket stubs$q$, $q$عشرون قصاصة تذكرة$q$, 4, 39, 27, 49, $q$The ticket tally records 20 tickets sold at 10 credits each, for 200 credits received.$q$, $q$يسجل كشف التذاكر بيع ٢٠ تذكرة بسعر ١٠ أرصدة للتذكرة؛ أي ٢٠٠ رصيد مستلَم.$q$, $q$مبلغ محصل تؤيده قصاصات التذاكر، لا مجرد توقع للمبيعات.$q$, $q$مبلغ محصل تؤيده قصاصات التذاكر، لا مجرد توقع للمبيعات.$q$, $q$FACT$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('212ff1c4-6b95-5673-9f8d-794824b3494a', '40a204a5-9efa-584c-a3af-fc33c9e00d7b', $q$craft_kit_sales$q$, $q$Twelve craft kits sold$q$, $q$Twelve craft kits sold$q$, $q$بيع اثنتي عشرة حقيبة فنية$q$, 32, 45, 35, 24, $q$The booth sheet records 12 craft kits at 15 credits each, for 180 credits received.$q$, $q$يسجل كشف الكشك بيع ١٢ حقيبة فنية بسعر ١٥ رصيدًا للحقيبة؛ أي ١٨٠ رصيدًا مستلَمًا.$q$, $q$هذا دخل محصل من البيع، وليس قيمة مخزون أو مبلغًا موعودًا.$q$, $q$هذا دخل محصل من البيع، وليس قيمة مخزون أو مبلغًا موعودًا.$q$, $q$FACT$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('0559e58c-07e2-5fea-bd6d-9494f22eca53', '40a204a5-9efa-584c-a3af-fc33c9e00d7b', $q$cash_donations$q$, $q$The counted donation jar$q$, $q$The counted donation jar$q$, $q$مرطبان التبرعات المعدود$q$, 70, 38, 18, 58, $q$The two-person count sheet lists 260 credits of donations physically received at the booth. It does not include pledge cards.$q$, $q$يسجل كشف العدّ المشترك ٢٦٠ رصيدًا من التبرعات التي استُلِمت نقدًا في الكشك. ولا يشمل بطاقات التعهد.$q$, $q$عند جمع ٢٠٠ + ١٨٠ + ٢٦٠ يصبح النقد المحصل ٦٤٠ رصيدًا.$q$, $q$عند جمع ٢٠٠ + ١٨٠ + ٢٦٠ يصبح النقد المحصل ٦٤٠ رصيدًا.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('b611ff06-c999-55e0-b7f8-09c3a09ce03f', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', 2, $q$The Accounts Desk$q$, $q$مكتب الحسابات$q$, 'demo/detective/missing-180/scene-2.webp', $q$A summary shows 820 credits, but the desk also holds three unpaid pledge cards and a handwritten calculation. Check what each number represents.$q$, $q$يظهر الملخص ٨٢٠ رصيدًا، لكن المكتب يضم أيضًا ثلاث بطاقات تعهد غير مدفوعة وحسابًا مكتوبًا يدويًا. تحقّق مما يمثله كل رقم.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('8748bcf1-1b4c-5133-b712-8b069a5028ef', 'b611ff06-c999-55e0-b7f8-09c3a09ce03f', $q$event_summary$q$, $q$The 820-credit summary$q$, $q$The 820-credit summary$q$, $q$ملخص الـ٨٢٠ رصيدًا$q$, 5, 27, 31, 44, $q$The closing summary labels 820 credits as the event total. Its total combines 640 credits received with 180 credits still expected; the column heading is easy to overlook.$q$, $q$يصنف ملخص الإغلاق ٨٢٠ رصيدًا على أنها إجمالي الفعالية. لكنه يجمع ٦٤٠ رصيدًا مستلَمًا و١٨٠ رصيدًا ما زالت متوقعة؛ وعنوان العمود سهل التجاوز.$q$, $q$الرقم صحيح بوصفه إجمالي النقد والتعهدات معًا، لكنه ليس إجمالي النقد المحصل.$q$, $q$الرقم صحيح بوصفه إجمالي النقد والتعهدات معًا، لكنه ليس إجمالي النقد المحصل.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('0223e7b2-27f9-575f-91b2-84cbf0bc5342', 'b611ff06-c999-55e0-b7f8-09c3a09ce03f', $q$pending_pledges$q$, $q$Three pledge cards marked pending$q$, $q$Three pledge cards marked pending$q$, $q$ثلاث بطاقات تعهد معلّقة$q$, 37, 49, 29, 21, $q$Three cards promise 60 credits each. Each is marked pending—not paid—so the 180 credits have not yet been received.$q$, $q$تتعهد ثلاث بطاقات بمبلغ ٦٠ رصيدًا لكل منها. وكل بطاقة موسومة بأنها معلّقة وليست مدفوعة، لذا لم تُستلم الأرصدة الـ١٨٠ بعد.$q$, $q$يتطابق مجموع التعهدات غير المدفوعة مع فرق الـ١٨٠، لكن وجودها لا يثبت أن أحدًا أخذ مالًا.$q$, $q$يتطابق مجموع التعهدات غير المدفوعة مع فرق الـ١٨٠، لكن وجودها لا يثبت أن أحدًا أخذ مالًا.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('7189300c-5a81-5d1f-b553-02da510a8b2f', 'b611ff06-c999-55e0-b7f8-09c3a09ce03f', $q$summary_calculation$q$, $q$The calculation beside the summary$q$, $q$The calculation beside the summary$q$, $q$الحساب المكتوب بجوار الملخص$q$, 55, 70, 22, 19, $q$A working note adds the 640-credit cash subtotal to the 180-credit pending pledges to reach 820. It is a mixed total, not a cash count.$q$, $q$يجمع حساب العمل ٦٤٠ رصيدًا من النقد مع ١٨٠ رصيدًا من التعهدات المعلّقة ليصل إلى ٨٢٠. إنه إجمالي مختلط وليس عدًّا للنقد.$q$, $q$يشرح مصدر فرق الحساب مباشرة، من دون تحديد خطأ متعمد أو فاعل لسرقة.$q$, $q$يشرح مصدر فرق الحساب مباشرة، من دون تحديد خطأ متعمد أو فاعل لسرقة.$q$, $q$OBSERVATION$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('78bf2f6f-a4c0-5874-9db9-e2aabeb746de', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', 3, $q$The Deposit Counter$q$, $q$منضدة الإيداع$q$, 'demo/detective/missing-180/scene-3.webp', $q$The cash bag was counted, sealed, and deposited. Compare the amount at each handoff and check whether the seal record matches.$q$, $q$عُدّ كيس النقد وخُتم وأُودع. قارن المبلغ عند كل تسليم وتحقق من تطابق سجل الختم.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('7f799fb8-1217-5a53-8f74-435e4359da67', '78bf2f6f-a4c0-5874-9db9-e2aabeb746de', $q$witnessed_cash_count$q$, $q$Two witnesses count 640 credits$q$, $q$Two witnesses count 640 credits$q$, $q$شاهدا العدّ يثبتان ٦٤٠ رصيدًا$q$, 8, 30, 26, 41, $q$Mariam and Rasha signed the closing sheet confirming that the sealed bag contained 640 credits after the booth receipts were reconciled.$q$, $q$وقّعت مريم ورشا كشف الإغلاق لتأكيد أن الكيس المختوم احتوى ٦٤٠ رصيدًا بعد مطابقة إيصالات الكشك.$q$, $q$يؤيد العدّ المشترك مبلغ النقد الفعلي، لكنه لا يثبت وحده كل ما جرى قبل العد.$q$, $q$يؤيد العدّ المشترك مبلغ النقد الفعلي، لكنه لا يثبت وحده كل ما جرى قبل العد.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('01f620bc-d922-5b20-83c3-bc389f2cd5a9', '78bf2f6f-a4c0-5874-9db9-e2aabeb746de', $q$bank_deposit_receipt$q$, $q$The bank receipt for 640$q$, $q$The bank receipt for 640$q$, $q$إيصال البنك بمبلغ ٦٤٠$q$, 38, 29, 27, 42, $q$The bank deposit receipt records 640 credits—the same amount as the witnessed cash count.$q$, $q$يسجل إيصال الإيداع البنكي ٦٤٠ رصيدًا، وهو المبلغ نفسه الذي أثبته العدّ المشترك.$q$, $q$لا يظهر اختلاف بين النقد المعدود والمبلغ المودع لدى البنك.$q$, $q$لا يظهر اختلاف بين النقد المعدود والمبلغ المودع لدى البنك.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('49a4be9c-76c6-5c18-944f-bb0cb442d4d9', '78bf2f6f-a4c0-5874-9db9-e2aabeb746de', $q$matching_seal$q$, $q$The unbroken matching seal$q$, $q$The unbroken matching seal$q$, $q$الختم المطابق غير المكسور$q$, 70, 41, 25, 38, $q$The bag's seal number matches the handoff log and is recorded as intact at the bank. This supports an accounted-for handoff after the witnessed count.$q$, $q$يطابق رقم ختم الكيس سجل التسليم، وسُجل الختم سليمًا عند البنك. يدعم ذلك توثيق التسليم بعد العدّ المشترك.$q$, $q$قرينة على سلامة مرحلة النقل بعد العدّ، وليست دليلًا قاطعًا على كل مرحلة سابقة.$q$, $q$قرينة على سلامة مرحلة النقل بعد العدّ، وليست دليلًا قاطعًا على كل مرحلة سابقة.$q$, $q$OBSERVATION$q$, 3, '{}'::jsonb) on conflict (id) do nothing;
