insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('1080a70b-5bc6-5abb-a933-14f3ce534959', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '0223e7b2-27f9-575f-91b2-84cbf0bc5342', '8748bcf1-1b4c-5133-b712-8b069a5028ef', $q$CONTEXTUAL$q$, $q$The three unpaid promises explain the extra 180 in the mixed event total, but they are not cash received.$q$, $q$تفسر التعهدات الثلاثة غير المدفوعة زيادة ١٨٠ في إجمالي الفعالية المختلط، لكنها ليست نقدًا مستلمًا.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('28386d9a-3939-564e-a4c5-63f0c5964dbd', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '7f799fb8-1217-5a53-8f74-435e4359da67', '01f620bc-d922-5b20-83c3-bc389f2cd5a9', $q$SUPPORTS$q$, $q$The witnessed count and bank receipt independently report the same 640-credit amount.$q$, $q$يسجل العدّ المشهود وإيصال البنك بصورة مستقلة المبلغ نفسه: ٦٤٠ رصيدًا.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('aceac30b-fbb4-52c5-b215-c59e332d7d4f', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '49a4be9c-76c6-5c18-944f-bb0cb442d4d9', '01f620bc-d922-5b20-83c3-bc389f2cd5a9', $q$TEMPORAL$q$, $q$The matching intact seal documents the handoff after the joint count.$q$, $q$يوثق الختم السليم المطابق التسليم الذي أعقب العدّ المشترك.$q$) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('c6b342b0-807b-5500-86d2-e04a74c51215', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '3bf8752c-f21d-59de-b20b-2e2e0f989f10', $q$MULTIPLE_CHOICE$q$, $q$What do the ticket records show was actually received?$q$, $q$ماذا تثبت سجلات التذاكر أنه تم تحصيله فعلًا؟$q$, $q$[{"id":"a","text":"20 tickets × 10 credits = 200 credits","text_ar":"٢٠ تذكرة × ١٠ أرصدة = ٢٠٠ رصيد"},{"id":"b","text":"Three pledges = 180 credits received","text_ar":"ثلاثة تعهدات = ١٨٠ رصيدًا مستلَمًا"},{"id":"c","text":"820 credits in cash","text_ar":"٨٢٠ رصيدًا نقدًا"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$مبلغ محصل تؤيده قصاصات التذاكر، لا مجرد توقع للمبيعات.$q$, $q$مبلغ محصل تؤيده قصاصات التذاكر، لا مجرد توقع للمبيعات.$q$, array['6693a1ef-14d2-50b8-94fc-f31ac66849cb'::uuid]::uuid[], 8, -2, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('d86cd0ee-7401-5dfe-8fc6-b12d21dc859c', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '3bf8752c-f21d-59de-b20b-2e2e0f989f10', $q$MULTIPLE_CHOICE$q$, $q$Add ticket sales, craft-kit sales, and cash donations. How much cash was collected at the fair?$q$, $q$اجمع مبيعات التذاكر والحقائب الفنية والتبرعات النقدية. كم بلغ النقد المحصل في المعرض؟$q$, $q$[{"id":"a","text":"640 credits","text_ar":"٦٤٠ رصيدًا"},{"id":"b","text":"820 credits","text_ar":"٨٢٠ رصيدًا"},{"id":"c","text":"460 credits","text_ar":"٤٦٠ رصيدًا"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$مبلغ محصل تؤيده قصاصات التذاكر، لا مجرد توقع للمبيعات.$q$, $q$مبلغ محصل تؤيده قصاصات التذاكر، لا مجرد توقع للمبيعات.$q$, array['6693a1ef-14d2-50b8-94fc-f31ac66849cb'::uuid,'212ff1c4-6b95-5673-9f8d-794824b3494a'::uuid,'0559e58c-07e2-5fea-bd6d-9494f22eca53'::uuid]::uuid[], 12, -3, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('8d4b4477-543a-5bbb-bbe7-18e2402accfd', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '3bf8752c-f21d-59de-b20b-2e2e0f989f10', $q$TRUE_FALSE$q$, $q$A signed pledge card is the same as cash already received.$q$, $q$بطاقة التعهد الموقعة تعادل نقدًا تم استلامه بالفعل.$q$, $q$[]$q$::jsonb, $q${"value":"false"}$q$::jsonb, '[]'::jsonb, $q$يتطابق مجموع التعهدات غير المدفوعة مع فرق الـ١٨٠، لكن وجودها لا يثبت أن أحدًا أخذ مالًا.$q$, $q$يتطابق مجموع التعهدات غير المدفوعة مع فرق الـ١٨٠، لكن وجودها لا يثبت أن أحدًا أخذ مالًا.$q$, array['0223e7b2-27f9-575f-91b2-84cbf0bc5342'::uuid]::uuid[], 8, -2, 3) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('5a64382d-cf42-53c6-9b47-d1b51873bc00', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '2ddad7e2-b2b3-5054-86ab-5372ca94385e', $q$MULTIPLE_CHOICE$q$, $q$Why does the event summary show 820 when the cash receipts total 640?$q$, $q$لماذا يظهر ملخص الفعالية ٨٢٠ بينما يبلغ مجموع الإيصالات النقدية ٦٤٠؟$q$, $q$[{"id":"a","text":"It adds 180 credits of unpaid pledges to the cash total","text_ar":"أضاف ١٨٠ رصيدًا من التعهدات غير المدفوعة إلى مجموع النقد"},{"id":"b","text":"The bank created 180 extra credits","text_ar":"أنشأ البنك ١٨٠ رصيدًا إضافيًا"},{"id":"c","text":"The ticket total was counted twice","text_ar":"حُسبت التذاكر مرتين"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$الرقم صحيح بوصفه إجمالي النقد والتعهدات معًا، لكنه ليس إجمالي النقد المحصل.$q$, $q$الرقم صحيح بوصفه إجمالي النقد والتعهدات معًا، لكنه ليس إجمالي النقد المحصل.$q$, array['8748bcf1-1b4c-5133-b712-8b069a5028ef'::uuid,'0223e7b2-27f9-575f-91b2-84cbf0bc5342'::uuid,'7189300c-5a81-5d1f-b553-02da510a8b2f'::uuid]::uuid[], 12, -3, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('e8c1b3cf-0724-55ef-bed7-07504fc1f715', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '2ddad7e2-b2b3-5054-86ab-5372ca94385e', $q$MULTIPLE_CHOICE$q$, $q$Match the 180-credit difference with the record that explains it.$q$, $q$اربط فرق الـ١٨٠ رصيدًا بالسجل الذي يفسره.$q$, $q$[{"id":"a","text":"Three unpaid promises of 60 credits each","text_ar":"ثلاثة وعود غير مدفوعة، قيمة كل منها ٦٠ رصيدًا"},{"id":"b","text":"A bank fee of 180 credits","text_ar":"رسوم بنك بقيمة ١٨٠ رصيدًا"},{"id":"c","text":"A missing sealed bag","text_ar":"كيس مختوم مفقود"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$يتطابق مجموع التعهدات غير المدفوعة مع فرق الـ١٨٠، لكن وجودها لا يثبت أن أحدًا أخذ مالًا.$q$, $q$يتطابق مجموع التعهدات غير المدفوعة مع فرق الـ١٨٠، لكن وجودها لا يثبت أن أحدًا أخذ مالًا.$q$, array['0223e7b2-27f9-575f-91b2-84cbf0bc5342'::uuid,'7189300c-5a81-5d1f-b553-02da510a8b2f'::uuid]::uuid[], 10, -2, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('3050e590-a74e-5acd-a3c2-36cb5b7698aa', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '2ddad7e2-b2b3-5054-86ab-5372ca94385e', $q$MULTIPLE_CHOICE$q$, $q$Which independent record confirms the amount reached the bank?$q$, $q$أي سجل مستقل يؤكد المبلغ الذي وصل إلى البنك؟$q$, $q$[{"id":"a","text":"The bank deposit receipt for 640 credits","text_ar":"إيصال البنك بإيداع ٦٤٠ رصيدًا"},{"id":"b","text":"The event's fundraising target","text_ar":"الهدف المالي للفعالية"},{"id":"c","text":"Nabil's memory of the pledges","text_ar":"تذكر نبيل للتعهدات"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$يؤيد العدّ المشترك مبلغ النقد الفعلي، لكنه لا يثبت وحده كل ما جرى قبل العد.$q$, $q$يؤيد العدّ المشترك مبلغ النقد الفعلي، لكنه لا يثبت وحده كل ما جرى قبل العد.$q$, array['7f799fb8-1217-5a53-8f74-435e4359da67'::uuid,'01f620bc-d922-5b20-83c3-bc389f2cd5a9'::uuid,'49a4be9c-76c6-5c18-944f-bb0cb442d4d9'::uuid]::uuid[], 12, -3, 3) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('8cdf86b9-c07e-56a6-8a7f-5d0de9f8b071', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '825d4817-85f9-5820-97c4-74301af7a98e', $q$MULTIPLE_CHOICE$q$, $q$Which claim goes beyond the evidence currently available?$q$, $q$أي ادعاء يتجاوز الأدلة المتاحة حاليًا؟$q$, $q$[{"id":"a","text":"The cash count and bank deposit both show 640","text_ar":"يظهر عدّ النقد والإيداع البنكي ٦٤٠ كليهما"},{"id":"b","text":"A specific volunteer stole exactly 180 credits","text_ar":"سرق متطوع محدد ١٨٠ رصيدًا بالضبط"},{"id":"c","text":"The summary included unpaid pledges","text_ar":"تضمن الملخص تعهدات غير مدفوعة"}]$q$::jsonb, $q${"option_id":"b"}$q$::jsonb, '[]'::jsonb, $q$يتطابق مجموع التعهدات غير المدفوعة مع فرق الـ١٨٠، لكن وجودها لا يثبت أن أحدًا أخذ مالًا.$q$, $q$يتطابق مجموع التعهدات غير المدفوعة مع فرق الـ١٨٠، لكن وجودها لا يثبت أن أحدًا أخذ مالًا.$q$, array['0223e7b2-27f9-575f-91b2-84cbf0bc5342'::uuid,'7f799fb8-1217-5a53-8f74-435e4359da67'::uuid,'01f620bc-d922-5b20-83c3-bc389f2cd5a9'::uuid]::uuid[], 15, -4, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('a5fa8931-ff0c-52e0-8ebb-a1108d839f78', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '825d4817-85f9-5820-97c4-74301af7a98e', $q$MULTIPLE_CHOICE$q$, $q$What additional information would best resolve whether any separate cash was ever collected but not recorded?$q$, $q$ما المعلومة الإضافية الأفضل للتحقق مما إذا كان قد جُمع نقد آخر ولم يُسجل؟$q$, $q$[{"id":"a","text":"Original numbered receipts and the spreadsheet edit history","text_ar":"الإيصالات الأصلية المرقمة وسجل تعديلات جدول الحسابات"},{"id":"b","text":"A guess about who looked nervous","text_ar":"تخمين عمّن بدا متوترًا"},{"id":"c","text":"A photo of the empty booth","text_ar":"صورة للكشك بعد إخلائه"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$مبلغ محصل تؤيده قصاصات التذاكر، لا مجرد توقع للمبيعات.$q$, $q$مبلغ محصل تؤيده قصاصات التذاكر، لا مجرد توقع للمبيعات.$q$, array['6693a1ef-14d2-50b8-94fc-f31ac66849cb'::uuid,'8748bcf1-1b4c-5133-b712-8b069a5028ef'::uuid,'7f799fb8-1217-5a53-8f74-435e4359da67'::uuid]::uuid[], 15, -4, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('f9535be7-0266-542d-a564-40f717ef3dcc', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '825d4817-85f9-5820-97c4-74301af7a98e', $q$FINAL_CONCLUSION$q$, $q$What is the fairest conclusion from the records?$q$, $q$ما الاستنتاج الأكثر إنصافًا الذي تدعمه السجلات؟$q$, $q$[{"id":"a","text":"640 credits were collected and deposited; 180 credits were pledged but still pending, so the mismatch alone does not prove theft","text_ar":"تم تحصيل ٦٤٠ رصيدًا وإيداعها؛ أما ١٨٠ رصيدًا فكانت تعهدات معلّقة، لذا لا يثبت اختلاف الإجمالي وحده وقوع سرقة"},{"id":"b","text":"Nabil definitely stole 180 credits","text_ar":"سرق نبيل ١٨٠ رصيدًا بالتأكيد"},{"id":"c","text":"The bank kept 180 credits","text_ar":"احتفظ البنك بـ١٨٠ رصيدًا"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$The records reconcile without a demonstrated cash loss. Ticket sales produced 200 credits, craft-kit sales 180, and received cash donations 260: a total of 640. The signed count and bank receipt both show 640. The other 180 consists of three 60-credit pledges marked pending. The closing summary combined received cash with expected pledges and mislabeled the combined figure as collected money. The records support a reporting/classification error, not a proven theft or a proven dishonest person. If concern remains about additional unrecorded receipts, review original numbered receipts and the spreadsheet edit history.$q$, $q$تتطابق السجلات من دون ثبوت نقص في النقد: بلغت مبيعات التذاكر ٢٠٠ رصيد، والحقائب الفنية ١٨٠، والتبرعات النقدية المستلمة ٢٦٠؛ أي ٦٤٠ رصيدًا. ويثبت كشف العدّ الموقع وإيصال البنك المبلغ نفسه. أما الـ١٨٠ الأخرى فهي ثلاثة تعهدات بقيمة ٦٠ لكل منها، وما زالت معلّقة. جمع ملخص الإغلاق النقد المستلَم بالتعهدات المتوقعة ووصف الإجمالي المختلط خطأً بأنه مال محصل. تدعم السجلات خطأً في التصنيف أو إعداد التقرير، لا سرقة مثبتة ولا إدانة لشخص بعينه. وإذا بقي قلق من إيصالات إضافية غير مسجلة، فينبغي مراجعة الإيصالات الأصلية المرقمة وسجل تعديلات جدول الحسابات.$q$, array['6693a1ef-14d2-50b8-94fc-f31ac66849cb'::uuid,'212ff1c4-6b95-5673-9f8d-794824b3494a'::uuid,'0559e58c-07e2-5fea-bd6d-9494f22eca53'::uuid,'0223e7b2-27f9-575f-91b2-84cbf0bc5342'::uuid,'7f799fb8-1217-5a53-8f74-435e4359da67'::uuid,'01f620bc-d922-5b20-83c3-bc389f2cd5a9'::uuid]::uuid[], 20, -5, 3) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('efd72e59-37ec-5225-a7de-6bd8a2a37e62', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', $q$Mariam Adel$q$, $q$مريم عادل$q$, $q$Prepared the closing summary and co-signed the cash count.$q$, $q$أعدّت ملخص الإغلاق وشاركت في توقيع عدّ النقد. تقول إنها نقلت كل البنود الظاهرة في ورقة التخطيط إلى الملخص.$q$, $q$أمينة صندوق الفعالية$q$, $q$Event treasurer$q$, $q${"18:00":"Closing summary prepared","18:12":"Cash count co-signed"}$q$::jsonb, $q$تؤكد أن عدّ النقد تم بحضور رشا وأنها لم تعتبر التعهدات نقودًا مستلمة عمدًا.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('5498b501-150a-50a8-8783-33160324ad27', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', $q$Nabil Samir$q$, $q$نبيل سمير$q$, $q$Collected pledge cards and helped at the donation booth.$q$, $q$جمع بطاقات التعهد وساعد في كشك التبرعات. يتذكر وعودًا بثلاثة تبرعات كبيرة، لكنه لا يملك إيصالات تثبت استلامها نقدًا.$q$, $q$متطوع طاولة التبرعات$q$, $q$Donation-table volunteer$q$, $q${"17:40":"Pledge cards gathered","18:00":"Booth closes"}$q$::jsonb, $q$قال في البداية إن كل التعهدات سُددت في يوم الفعالية، ثم أوضح أنه كان يقصد أنها وُعدت.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('a8d12c4c-9c9f-5c27-83e5-6b359e50bd3e', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', $q$Rasha Fouad$q$, $q$رشا فؤاد$q$, $q$Verified the physical cash count and accompanied the sealed bag to the bank handoff.$q$, $q$تحققت من عدّ النقد الفعلي ورافقت تسليم الكيس المختوم للبنك. وقّعت كشفًا مشتركًا يطابق إيصالات البيع والتبرعات النقدية.$q$, $q$شاهدة العدّ الثانية$q$, $q$Second cash counter$q$, $q${"18:12":"Cash count co-signed","18:25":"Sealed bag handed over"}$q$::jsonb, $q$تقول إن الكيس احتوى ٦٤٠ رصيدًا عند الختم والتسليم.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('d6547810-5d84-5b41-9eab-284700af8823', 'efd72e59-37ec-5225-a7de-6bd8a2a37e62', $q$The 820 figure included the three pending pledges as well as the cash. I should have labelled it expected total, not cash collected.$q$, $q$تضمن رقم ٨٢٠ التعهدات الثلاثة المعلّقة إلى جانب النقد. كان ينبغي أن أسميه الإجمالي المتوقع لا النقد المحصل.$q$, $q$TRUE$q$, array['8748bcf1-1b4c-5133-b712-8b069a5028ef'::uuid,'0223e7b2-27f9-575f-91b2-84cbf0bc5342'::uuid,'7189300c-5a81-5d1f-b553-02da510a8b2f'::uuid]::uuid[], $q$تتفق مريم مع الحساب الظاهر. يشير ذلك إلى خطأ في تسمية الإجمالي، ولا يثبت نية احتيال.$q$, $q$تتفق مريم مع الحساب الظاهر. يشير ذلك إلى خطأ في تسمية الإجمالي، ولا يثبت نية احتيال.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('c2f58cfe-204d-5cdd-8811-b8dacaac3035', '5498b501-150a-50a8-8783-33160324ad27', $q$All three large pledges were paid in cash before closing.$q$, $q$دُفعت التعهدات الكبيرة الثلاثة نقدًا قبل الإغلاق.$q$, $q$INCOMPLETE$q$, array['0223e7b2-27f9-575f-91b2-84cbf0bc5342'::uuid,'0559e58c-07e2-5fea-bd6d-9494f22eca53'::uuid,'7f799fb8-1217-5a53-8f74-435e4359da67'::uuid]::uuid[], $q$تسجل البطاقات التعهدات بأنها معلّقة ولا تظهر إيصالات دفع. قد يكون نبيل خلط بين الوعد والدفع؛ ولا تكفي السجلات الحالية للجزم بأنه كذب عمدًا.$q$, $q$تسجل البطاقات التعهدات بأنها معلّقة ولا تظهر إيصالات دفع. قد يكون نبيل خلط بين الوعد والدفع؛ ولا تكفي السجلات الحالية للجزم بأنه كذب عمدًا.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('fed7a3f6-1e09-5ab2-bbf2-c7bf66a36145', 'a8d12c4c-9c9f-5c27-83e5-6b359e50bd3e', $q$Mariam and I counted 640 credits, sealed the bag, and the bank recorded the same amount.$q$, $q$عددنا أنا ومريم ٦٤٠ رصيدًا، وختمنا الكيس، وسجل البنك المبلغ نفسه.$q$, $q$TRUE$q$, array['7f799fb8-1217-5a53-8f74-435e4359da67'::uuid,'01f620bc-d922-5b20-83c3-bc389f2cd5a9'::uuid,'49a4be9c-76c6-5c18-944f-bb0cb442d4d9'::uuid]::uuid[], $q$تتفق إفادة رشا مع كشف العدّ وإيصال البنك وسجل الختم.$q$, $q$تتفق إفادة رشا مع كشف العدّ وإيصال البنك وسجل الختم.$q$) on conflict (id) do nothing;
