insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('3a8bd506-8fcd-5696-8498-09f404e90b83', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '3bf8752c-f21d-59de-b20b-2e2e0f989f10', $q$Keep ticket sales, kit sales, and donations in separate lines before adding them.$q$, $q$أبقِ مبيعات التذاكر والحقائب والتبرعات في بنود منفصلة قبل جمعها.$q$, '{}'::jsonb, -1, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('bb7e2496-905c-59ce-9384-bc2d6b9fbac1', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '2ddad7e2-b2b3-5054-86ab-5372ca94385e', $q$Check the status word on each pledge card: promised is not the same as paid.$q$, $q$تحقق من حالة كل بطاقة تعهد: الوعد ليس هو الدفع.$q$, '{}'::jsonb, -2, 2) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('e2caff87-fc27-5930-b57a-687b816f0322', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', '825d4817-85f9-5820-97c4-74301af7a98e', $q$Compare the physical cash count with the bank receipt, then explain the remaining 180 without naming a thief unless evidence supports it.$q$, $q$قارن عدّ النقد الفعلي بإيصال البنك، ثم فسّر الـ١٨٠ المتبقية دون اتهام أحد ما لم تدعم الأدلة ذلك.$q$, '{}'::jsonb, -3, 3) on conflict (id) do nothing;
insert into detective_solutions(id, version_id, public_reveal, public_reveal_ar, solution_key, alternative_hypotheses, educational_explanation, educational_explanation_ar) values ('013fac61-6ac0-560b-8c20-486fdc058557', '835f7821-1010-5deb-aaa2-84e4d64e6ee1', $q$The records reconcile without a demonstrated cash loss. Ticket sales produced 200 credits, craft-kit sales 180, and received cash donations 260: a total of 640. The signed count and bank receipt both show 640. The other 180 consists of three 60-credit pledges marked pending. The closing summary combined received cash with expected pledges and mislabeled the combined figure as collected money. The records support a reporting/classification error, not a proven theft or a proven dishonest person. If concern remains about additional unrecorded receipts, review original numbered receipts and the spreadsheet edit history.$q$, $q$تتطابق السجلات من دون ثبوت نقص في النقد: بلغت مبيعات التذاكر ٢٠٠ رصيد، والحقائب الفنية ١٨٠، والتبرعات النقدية المستلمة ٢٦٠؛ أي ٦٤٠ رصيدًا. ويثبت كشف العدّ الموقع وإيصال البنك المبلغ نفسه. أما الـ١٨٠ الأخرى فهي ثلاثة تعهدات بقيمة ٦٠ لكل منها، وما زالت معلّقة. جمع ملخص الإغلاق النقد المستلَم بالتعهدات المتوقعة ووصف الإجمالي المختلط خطأً بأنه مال محصل. تدعم السجلات خطأً في التصنيف أو إعداد التقرير، لا سرقة مثبتة ولا إدانة لشخص بعينه. وإذا بقي قلق من إيصالات إضافية غير مسجلة، فينبغي مراجعة الإيصالات الأصلية المرقمة وسجل تعديلات جدول الحسابات.$q$, $q${"final_question":"f9535be7-0266-542d-a564-40f717ef3dcc"}$q$::jsonb, $q$[{"en":"Nabil stole exactly 180 credits.","ar":"سرق نبيل ١٨٠ رصيدًا بالضبط.","why_wrong_en":"The 180 matches three pending 60-credit promises. The current records do not show cash was collected on those promises or that Nabil took it. This does not prove that no other unrecorded issue could ever exist; original receipts and edit history would help check that.","why_wrong_ar":"يطابق مبلغ ١٨٠ ثلاثة تعهدات معلّقة، قيمة كل منها ٦٠. ولا تثبت السجلات الحالية أن هذه المبالغ دُفعت أو أن نبيل أخذها. وهذا لا يبرهن استحالة وجود مشكلة أخرى غير مسجلة؛ فالإيصالات الأصلية وسجل التعديلات يساعدان على التحقق."},{"en":"The bank kept 180 credits.","ar":"احتفظ البنك بـ١٨٠ رصيدًا.","why_wrong_en":"The bank receipt matches the witnessed 640-credit deposit. The apparent difference already has a documented explanation in the pending pledges.","why_wrong_ar":"يطابق إيصال البنك الإيداع المشهود البالغ ٦٤٠ رصيدًا. وللفرق الظاهري تفسير موثق في التعهدات المعلّقة."},{"en":"The event earned 820 credits in cash.","ar":"جمعت الفعالية ٨٢٠ رصيدًا نقدًا.","why_wrong_en":"The 820 total includes expected but unpaid pledges; the receipts and bank record support 640 received credits.","why_wrong_ar":"يتضمن إجمالي ٨٢٠ تعهدات متوقعة لم تُدفع؛ وتدعم الإيصالات وسجل البنك تحصيل ٦٤٠ رصيدًا."}]$q$::jsonb, $q$Financial investigations should reconcile source records before naming a culprit. Add only amounts actually received, keep pledges separate from cash, and compare a witnessed count with the bank receipt. Here the arithmetic explains the full 180-credit difference, but the records still do not justify declaring that no other error is possible. The fair conclusion is limited to what these documents support.$q$, $q$ينبغي للتحقيق المالي مطابقة السجلات الأصلية قبل تسمية متهم. اجمع المبالغ المستلمة فعلًا فقط، وافصل التعهدات عن النقد، وقارن العدّ المشهود بإيصال البنك. تفسر الحسابات هنا فرق الـ١٨٠ كاملًا، لكن السجلات لا تبرر الجزم باستحالة وجود أي خطأ آخر. ينبغي أن يظل الاستنتاج ضمن ما تدعمه هذه الوثائق.$q$) on conflict (id) do nothing;
